drafts.2:
h1 {
  text-align: center;
  font-size: 32px;
}

p {
  text-align: center;
}

drafts.4:
ul {
  display: flex;
  list-style-type: none;
  gap: 16px;
}

a {
  text-decoration: none;
}

drafts.5:
table {
  width: 100%;
  border-collapse: collapse;
}

th, td {
  border: 1px solid #d1d5db;
  padding: 8px;
}

th {
  background-color: #dbeafe;
}

drafts.6:
form {
  padding: 16px;
  background-color: #f3f4f6;
  border-radius: 8px;
}

input {
  width: 100%;
}

drafts.7:
.card {
  max-width: 360px;
  margin: 0 auto;
  background-color: #ffffff;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
  padding: 24px;
}
